//! Per-handle policy for the forced tool choice and the structured-output path.

use std::sync::atomic::{AtomicBool, Ordering};

use crate::family::{rejects_forced_tool_choice, ModelFamily};

/// The wire path that carries a structured-output or forced-tool request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum OutputPath {
    /// Use a synthetic forced tool.
    ForcedTool,
    /// Use the native structured-output field.
    Native,
}

/// A notice that the native path changes the request. Each kind is logged once per handle.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum NativeNotice {
    /// `ToolChoice::Required` is omitted.
    RequiredOmitted,
    /// `ToolChoice::Tool` is omitted.
    ToolOmitted,
    /// `ResponseFormat::JsonObject` degrades to text.
    JsonObjectAsText,
}

/// State that selects the output path for one model handle.
#[derive(Debug)]
pub(crate) struct ForcedChoicePolicy {
    rejects_static: bool,
    learned: AtomicBool,
    family: ModelFamily,
    warned: [AtomicBool; 3],
}

impl ForcedChoicePolicy {
    /// Make a policy. The static rule comes from the model id.
    pub(crate) fn new(model_id: &str, family: ModelFamily) -> Self {
        Self::with_rule(rejects_forced_tool_choice(model_id), family)
    }

    /// Make a policy with no static rule.
    #[cfg(test)]
    pub(crate) fn without_static_rule(family: ModelFamily) -> Self {
        Self::with_rule(false, family)
    }

    fn with_rule(rejects_static: bool, family: ModelFamily) -> Self {
        Self {
            rejects_static,
            learned: AtomicBool::new(false),
            family,
            warned: [
                AtomicBool::new(false),
                AtomicBool::new(false),
                AtomicBool::new(false),
            ],
        }
    }

    /// The model family of this handle.
    pub(crate) fn family(&self) -> ModelFamily {
        self.family
    }

    /// The output path for the next request.
    pub(crate) fn path(&self) -> OutputPath {
        if self.rejects_static || self.learned.load(Ordering::SeqCst) {
            OutputPath::Native
        } else {
            OutputPath::ForcedTool
        }
    }

    /// Record that the service rejected a forced tool choice. Returns `true` only for the first call.
    pub(crate) fn record_rejection(&self) -> bool {
        !self.learned.swap(true, Ordering::SeqCst)
    }

    /// Returns `true` only the first time for each notice kind.
    pub(crate) fn first_notice(&self, n: NativeNotice) -> bool {
        !self.warned[n as usize].swap(true, Ordering::SeqCst)
    }

    /// Log the notice once per handle.
    pub(crate) fn note(&self, n: NativeNotice, model_id: &str) {
        if !self.first_notice(n) {
            return;
        }
        let text = match n {
            NativeNotice::RequiredOmitted => {
                "ToolChoice::Required is omitted: this model rejects a forced tool choice"
            }
            NativeNotice::ToolOmitted => {
                "ToolChoice::Tool is omitted: this model rejects a forced tool choice"
            }
            NativeNotice::JsonObjectAsText => {
                "ResponseFormat::JsonObject degrades to text: native output cannot express a free-form object"
            }
        };
        tracing::warn!(target: "paigasus::bedrock::translate", model_id = %model_id, "{text}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ModelFamily::Anthropic;

    #[test]
    fn path_for_each_combination() {
        assert_eq!(
            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5-5", Anthropic).path(),
            OutputPath::Native
        );
        assert_eq!(
            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5", Anthropic).path(),
            OutputPath::ForcedTool
        );
        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
        assert_eq!(p.path(), OutputPath::ForcedTool);
        assert!(p.record_rejection());
        assert_eq!(p.path(), OutputPath::Native);
        let both = ForcedChoicePolicy::new("us.anthropic.claude-opus-5-5", Anthropic);
        both.record_rejection();
        assert_eq!(both.path(), OutputPath::Native);
    }

    #[test]
    fn record_rejection_is_true_only_once_across_threads() {
        let p = std::sync::Arc::new(ForcedChoicePolicy::without_static_rule(Anthropic));
        let firsts: usize = (0..8)
            .map(|_| {
                let p = p.clone();
                std::thread::spawn(move || p.record_rejection())
            })
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().unwrap() as usize)
            .sum();
        assert_eq!(firsts, 1);
    }

    #[test]
    fn first_notice_is_true_once_per_kind() {
        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
        assert!(p.first_notice(NativeNotice::RequiredOmitted));
        assert!(!p.first_notice(NativeNotice::RequiredOmitted));
        assert!(p.first_notice(NativeNotice::ToolOmitted));
        assert!(p.first_notice(NativeNotice::JsonObjectAsText));
    }
}
//! Bedrock model family detection and capability routing.

/// Identifies the model family of a Bedrock Converse model ID.
///
/// Used internally to select capability flags, schema rewriter rulesets, and
/// tool-choice support. The `#[non_exhaustive]` attribute allows future
/// additions without a breaking change.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum ModelFamily {
    /// Anthropic Claude model family (e.g. `anthropic.claude-*`).
    Anthropic,
    /// Amazon Nova model family (e.g. `amazon.nova-*`).
    AmazonNova,
    /// Amazon Titan model family (e.g. `amazon.titan-*`).
    AmazonTitan,
    /// Meta Llama model family (e.g. `meta.llama*`).
    Llama,
    /// Mistral model family (e.g. `mistral.mistral-*`).
    Mistral,
    /// Cohere Command model family (e.g. `cohere.command-*`).
    Cohere,
    /// Unknown or unrecognized model family.
    Unknown,
}

impl ModelFamily {
    /// Detect the model family from a Bedrock model ID.
    ///
    /// When the first segment is not a known provider name, detection reads
    /// the second segment. So a geographic prefix such as `us.`, `eu.`,
    /// `apac.`, `jp.`, `au.`, `ca.`, `in.` or `global.` is skipped, and a
    /// future prefix is skipped too. An ARN is classified by its resource ID
    /// (the text after the last `/`). Opaque IDs, such as application
    /// inference profile ARNs, give [`ModelFamily::Unknown`].
    ///
    /// # Examples
    ///
    /// ```
    /// use paigasus_helikon_providers_bedrock::ModelFamily;
    /// assert_eq!(
    ///     ModelFamily::from_model_id("anthropic.claude-3-5-sonnet-20241022-v2:0"),
    ///     ModelFamily::Anthropic,
    /// );
    /// assert_eq!(
    ///     ModelFamily::from_model_id("global.anthropic.claude-sonnet-5-5"),
    ///     ModelFamily::Anthropic,
    /// );
    /// ```
    pub fn from_model_id(model_id: &str) -> Self {
        let lowered = model_id.to_ascii_lowercase();
        let Some(id) = resource_id(&lowered) else {
            return Self::Unknown;
        };

        let (first, rest1) = id.split_once('.').unwrap_or((id, ""));
        let (second, rest2) = rest1.split_once('.').unwrap_or((rest1, ""));

        Self::classify(first, rest1)
            .or_else(|| Self::classify(second, rest2))
            .unwrap_or(if first.contains("llama") || second.contains("llama") {
                Self::Llama
            } else {
                Self::Unknown
            })
    }

    /// Map a provider segment (and the text after it) to a family, or `None`
    /// when the segment is not a known provider name.
    fn classify(provider: &str, rest: &str) -> Option<Self> {
        match provider {
            "anthropic" => Some(Self::Anthropic),
            "amazon" => Some(if rest.starts_with("nova") {
                Self::AmazonNova
            } else if rest.starts_with("titan") {
                Self::AmazonTitan
            } else {
                Self::Unknown
            }),
            "meta" => Some(Self::Llama),
            "mistral" => Some(Self::Mistral),
            "cohere" => Some(Self::Cohere),
            _ => None,
        }
    }

    /// Returns `true` when the family supports Bedrock's forced-tool-choice
    /// (`toolChoice: { tool: { name } }`) request field.
    ///
    /// Families that do not support it will have the `tool_choice` field
    /// omitted and a `debug!` log emitted instead.
    ///
    /// Some Anthropic models reject it. See [`rejects_forced_tool_choice`].
    pub(crate) fn supports_forced_tool_choice(self) -> bool {
        matches!(self, Self::Anthropic | Self::Mistral | Self::AmazonNova)
    }
}

/// Returns the resource ID of a lowercased model ID.
///
/// For an ARN, this is the text after the last `/`, or `None` when the ARN has
/// no `/`. Any other ID is returned unchanged.
fn resource_id(lowered: &str) -> Option<&str> {
    if lowered.starts_with("arn:") {
        lowered.rsplit_once('/').map(|(_, resource)| resource)
    } else {
        Some(lowered)
    }
}

